insert into public.abilities(id,game_version_id,banner_id,affiliation,name,timing,mechanics,stacking_rule,definition,active) select 'makeshift_guard',id,null,'wayfarer','Makeshift Guard','round_start','If an adjacent ally has 0 current armor, grant the frontmost such ally 1 temporary armor until round end.','Different bearers may protect the same ally, to a maximum of 2 temporary armor.','{"values":{"temporaryArmor":1,"targetsPerRound":1},"interactions":["Broken Formation suppresses this ability.","Temporary armor is removed before round-end damage.","An ally whose printed maximum armor is 0 remains eligible."]}'::jsonb,true from public.game_versions where status='active' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=null,affiliation='wayfarer',name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,affiliation,name,timing,mechanics,stacking_rule,definition,active) select 'roadwise',id,null,'wayfarer','Roadwise','after_targeted','The first time each battle this unit is selected by an enemy ability rather than an attack, clear Pin and gain +2 speed until after its next action.','Additional copies add no uses or speed.','{"values":{"speedBonus":2,"usesPerBattle":1},"interactions":["Direct attacks do not trigger it.","If the ability is cancelled, Roadwise still counts as used.","The speed bonus applies to the following round if the unit has already acted."]}'::jsonb,true from public.game_versions where status='active' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=null,affiliation='wayfarer',name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,affiliation,name,timing,mechanics,stacking_rule,definition,active) select 'contract_bond',id,null,'wayfarer','Contract Bond','battle_start','If the team contains exactly 2 Wayfarer troops, both gain +1 maximum health for the battle.','The team condition resolves once; multiple copies do not add more health.','{"values":{"requiredWayfarers":2,"maximumHealthBonus":1},"interactions":["Open Contract teams with 3 or 4 Wayfarers do not qualify.","Current health increases with maximum health.","A later defeat does not remove the bonus from the survivor."]}'::jsonb,true from public.game_versions where status='active' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=null,affiliation='wayfarer',name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,affiliation,name,timing,mechanics,stacking_rule,definition,active) select 'salvager',id,null,'wayfarer','Salvager','after_armor_break','The first time any other unit loses its last armor each round, restore 1 armor to this unit, not exceeding printed maximum armor.','Each bearer tracks its own use.','{"values":{"armorRestored":1,"usesPerRound":1},"interactions":["The broken unit may be allied or enemy.","An armor purge can trigger it.","A bearer with printed maximum armor 0 gains nothing and does not spend the use."]}'::jsonb,true from public.game_versions where status='active' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=null,affiliation='wayfarer',name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,affiliation,name,timing,mechanics,stacking_rule,definition,active) select 'field_ration',id,null,'wayfarer','Field Ration','round_end','At the end of rounds 3, 6, 9, and so on, restore 1 health to the wounded ally with the lowest health percentage; ties favor the frontmost.','Every bearer resolves separately in formation order.','{"values":{"healing":1,"everyNthRound":3},"interactions":["The bearer may heal itself.","Healing lock reduces the result to 0.","Resolve before fatigue."]}'::jsonb,true from public.game_versions where status='active' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=null,affiliation='wayfarer',name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
insert into public.abilities(id,game_version_id,banner_id,affiliation,name,timing,mechanics,stacking_rule,definition,active) select 'last_pay',id,null,'wayfarer','Last Pay','after_self_defeated','Adjacent allies gain +1 speed and +5 accuracy through the end of the next round.','Bonuses from different defeated bearers stack to +2 speed and +10 accuracy.','{"values":{"speedBonus":1,"accuracyBonus":5,"durationRounds":1},"interactions":["Broken Formation does not cancel a bonus already granted.","A Grave Recall return does not remove the bonus.","If no adjacent ally survives, nothing happens."]}'::jsonb,true from public.game_versions where status='active' on conflict(id) do update set game_version_id=excluded.game_version_id,banner_id=null,affiliation='wayfarer',name=excluded.name,timing=excluded.timing,mechanics=excluded.mechanics,stacking_rule=excluded.stacking_rule,definition=excluded.definition,active=true;
