begin;

alter table public.cards alter column banner_id drop not null;
alter table public.cards add column if not exists affiliation text not null default 'banner';
alter table public.cards drop constraint if exists cards_affiliation_check;
alter table public.cards add constraint cards_affiliation_check check ((affiliation='banner' and banner_id is not null) or (affiliation='wayfarer' and banner_id is null));
alter table public.abilities alter column banner_id drop not null;
alter table public.abilities add column if not exists affiliation text not null default 'banner';
alter table public.abilities drop constraint if exists abilities_affiliation_check;
alter table public.abilities add constraint abilities_affiliation_check check ((affiliation='banner' and banner_id is not null) or (affiliation='wayfarer' and banner_id is null));



commit;
